mapper.update:
UPDATE analysis_reference
   SET status = #{status}
     , fail_reason = #{failReason}
 WHERE reference_id = #{referenceId}

mapper.delete:
DELETE FROM analysis_relation
 WHERE revision_id = #{revisionId}
   AND relation_type IN ('OVERRIDES', 'CALLS_POSSIBLE_IMPLEMENTATION')

mapper.sql:
 WHERE r.revision_id = #{revisionId}
   AND r.status = #{status}
AND r.ref_kind = #{refKind}
AND  = #{cause}

AND md5() = #{causeKey}
AND r.name = #{name}
AND r.file_id = #{fileId}
AND f.path LIKE '%' || #{path} || '%'

 WHERE m.revision_id = #{revisionId}
AND s.fqn LIKE '%' || #{owner} || '%'
AND m.name = #{name}

mapper.select:
SELECT 
  FROM analysis_method m
  JOIN analysis_symbol s ON s.revision_id = m.revision_id AND s.symbol_id = m.owner_symbol_id
  JOIN analysis_file f ON f.file_id = m.file_id
 WHERE m.revision_id = #{revisionId}
   AND m.method_id = #{methodId}

choose.otherwise:
SELECT COUNT(DISTINCT t.from_id) AS "statements"
  FROM analysis_relation t
 WHERE t.revision_id = #{revisionId}
   AND t.to_external = #{target}
   AND t.relation_type IN
        #{type}

mapper.sql:
WITH RECURSIVE walk (depth, node_id, node_kind, conf) AS (


    SELECT 0, e.from_id::varchar, 'METHOD'::varchar
         , LEAST(, )
      FROM analysis_relation t
      JOIN analysis_relation e ON e.revision_id = t.revision_id AND e.to_id = t.from_id AND e.relation_type = 'EXECUTES_SQL'
     WHERE t.revision_id = #{revisionId}
       AND t.to_external = #{target}
       AND t.relation_type IN
            #{type}


    SELECT 0, e.from_id::varchar, 'METHOD'::varchar, 
      FROM analysis_relation e
     WHERE e.revision_id = #{revisionId}
       AND e.relation_type = 'EXECUTES_SQL'
       AND e.to_id IN (SELECT 'S' || mp.mapper_id
                         FROM analysis_mapper mp
                        WHERE mp.revision_id = #{revisionId}
                          AND (mp.statement_id = #{target} OR mp.namespace || '.' || mp.statement_id = #{target}))


    SELECT 0, m.method_id::varchar, 'METHOD'::varchar, 3
      FROM analysis_method m
      JOIN analysis_symbol s ON s.revision_id = m.revision_id AND s.symbol_id = m.owner_symbol_id
     WHERE m.revision_id = #{revisionId}
       AND s.fqn = #{target}


    SELECT 0, CAST(#{target} AS varchar), 'METHOD'::varchar, 3


    UNION
    SELECT w.depth + 1, r.from_id::varchar, r.from_kind::varchar
         , LEAST(w.conf, )
      FROM walk w
      JOIN analysis_relation r
        ON r.revision_id = #{revisionId}
       AND r.to_id = w.node_id
       AND r.relation_type IN
            #{type}
     WHERE w.depth < #{depth}
), affected AS (
    SELECT node_id, node_kind, MIN(depth) AS depth, MAX(conf) AS conf
      FROM walk
     GROUP BY node_id, node_kind
)
